inline bool equal_json(const J&a,const J&b){if(a.type!=b.type||a.scalar!=b.scalar||a.array.size()!=b.array.size()||a.object.size()!=b.object.size())return false;for(size_t i=0;i<a.array.size();++i)if(!equal_json(a.array[i],b.array[i]))return false;for(const auto&item:a.object){auto it=b.object.find(item.first);if(it==b.object.end()||!equal_json(item.second,it->second))return false;}return true;}

