 std::set<files::path> execution_files,producer_files,panel_roots;for(const auto&row:receipt.at("rows").array){files::path path=row.at("execution_file").scalar;require(execution_files.insert(path).second,"Duplicate execution path in replay");producer_files.insert(path.parent_path()/"producer.json");panel_roots.insert(path.parent_path().parent_path().parent_path().parent_path());}
