  match(arguments[0].scalar,j.at("binary_sha256").scalar);require(j.at("binary_sha256").scalar==protocol.at("expected_rho_binary_sha256").scalar,"Process binary differs from frozen protocol");binary_hashes.insert(j.at("binary_sha256").scalar);
