  const auto&envelope=j.at("resource_envelope");require(num(envelope.at("address_space_limit_bytes"))==12884901888ULL&&envelope.at("cpu_affinity").array.size()==1&&num(envelope.at("cpu_affinity").at(0))==3&&num(envelope.at("cpu_count"))==1&&num(envelope.at("threads"))==1&&real(envelope.at("timeout_s"))==60.,"Recorded CPU/memory/timeout envelope mismatch");++resource_checks;
