  auto observation=path.parent_path()/"observation.json";auto o=read_json(observation.string());match(path,o.at("process_receipt_sha256").scalar);match(target,o.at("target_file_sha256").scalar);match(config,o.at("config_file_sha256").scalar);require(o.at("status").scalar=="COMPLETED_VERIFIED"&&truth(o.at("verified"))&&!truth(o.at("wrong_answer")),"Observation completion flags false");hash(observation);++observation_checks;
