  const auto&provenance=manifest.at("source_and_input_provenance");match(provenance.at("protocol_path").scalar,provenance.at("protocol_sha256").scalar);require(provenance.at("protocol_sha256").scalar==expected_protocol,"Stage protocol source provenance differs from frozen protocol");match(provenance.at("executable").scalar,provenance.at("executable_sha256").scalar);match(provenance.at("rho_binary").scalar,provenance.at("rho_binary_sha256").scalar);
  auto runner_root=files::path(protocol.at("cwd").scalar)/"research/n83_speed_20261012/native_runner";const std::map<std::string,std::string> runner_sources={{"main","src/main.rs"},{"monitor","src/monitor.rs"},{"statistics","src/statistics.rs"},{"manifest","Cargo.toml"}};for(const auto&entry:runner_sources)match(runner_root/entry.second,provenance.at("compiled_source_sha256").at(entry.first).scalar);
